const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a polygon for a section of the Lower Mississippi River in Louisiana/Mississippi.
  // This polygon covers parts of the river near Baton Rouge/New Orleans.
  const geometry = ee.Geometry.Polygon(
    [[[-91.5, 31.0],
      [-90.5, 31.0],
      [-90.5, 29.5],
      [-91.5, 29.5],
      [-91.5, 31.0]]]);

  const date1_start = '2019-12-01';
  const date1_end = '2019-12-07'; // Around December 4, 2019
  const date2_start = '2020-01-30';
  const date2_end = '2020-02-05'; // Around February 2, 2020

  const S1_COLLECTION = 'COPERNICUS/S1_GRD';

  // Function to get and process Sentinel-1 data for a given date range
  const getWaterExtent = (startDate, endDate, name) => {
    let collection = ee.ImageCollection(S1_COLLECTION)
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('orbitProperties_pass', 'DESCENDING'))
      .filter(ee.Filter.eq('resolution_meters', 10))
      .filter(ee.Filter.eq('instrumentMode', 'IW'));

    if (collection.size().getInfo() === 0) {
      console.log(`No Sentinel-1 images found for ${name} (${startDate} to ${endDate}).`);
      return { area: null, pixelCount: 0, imageCount: 0 };
    }

    // Select the latest image to ensure closest proximity to the requested date, or mosaic.
    // Let's take the median to reduce speckle if multiple images are available.
    const image = collection.median().select('VV').clip(geometry);

    // Sentinel-1 VV backscatter for water is typically very low.
    // A threshold of -18 dB (linear scale: 0.0158) is commonly used.
    // Convert to linear scale if preferred, or use dB directly.
    // For this analysis, we will use -18 dB threshold on the dB values.
    const waterMask = image.lt(-18); // Pixels below -18 dB are considered water

    // Calculate area of water pixels
    const waterAreaImage = waterMask.multiply(ee.Image.pixelArea());

    const stats = waterAreaImage.reduceRegion({
      reducer: ee.Reducer.sum().unweighted(), // Use unweighted sum for area
      geometry: geometry,
      scale: 100, // Use 100m scale for efficiency and consistency
      maxPixels: 1e9,
      crs: 'EPSG:4326', // WGS84
      tileScale: 16 // Increase tileScale to avoid memory errors for large regions
    });

    const area = stats.get('VV').getInfo();

    const pixelCount = waterMask.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: 100,
        maxPixels: 1e9,
        crs: 'EPSG:4326',
        tileScale: 16
    }).get('VV').getInfo();

    return { area: area, pixelCount: pixelCount, imageCount: collection.size().getInfo() };
  };

  // 2. Data Acquisition & Check
  const result1 = getWaterExtent(date1_start, date1_end, 'Dec 2019');
  const result2 = getWaterExtent(date2_start, date2_end, 'Feb 2020');

  if (result1.area === null || result2.area === null) {
    console.log("C1: Empty Collection (No images found for one or both comparison points).");
    return;
  }

  // 3. Processing & Calculation (Check C2 and C3)
  if (result1.pixelCount === 0 || result2.pixelCount === 0) {
    console.log(`Dec 2019 Images: ${result1.imageCount}, Valid Pixels: ${result1.pixelCount}`);
    console.log(`Feb 2020 Images: ${result2.imageCount}, Valid Pixels: ${result2.pixelCount}`);
    console.log("C2: No Valid Pixels (Images exist, but after processing, 0 water pixels remain).");
    return;
  }

  const waterExtent1_km2 = result1.area / 1e6; // Convert m^2 to km^2
  const waterExtent2_km2 = result2.area / 1e6; // Convert m^2 to km^2

  if (waterExtent1_km2 === null || waterExtent2_km2 === null || isNaN(waterExtent1_km2) || isNaN(waterExtent2_km2)) {
    console.log("C3: Calculation Failure (Result is None, NaN, or invalid).");
    return;
  }

  // 4. Validation & Final Answer
  console.log(`Dec 2019 Images: ${result1.imageCount}, Valid Water Pixels: ${result1.pixelCount}`);
  console.log(`Feb 2020 Images: ${result2.imageCount}, Valid Water Pixels: ${result2.pixelCount}`);
  console.log(`Surface water extent on Dec 4, 2019 (approx.): ${waterExtent1_km2.toFixed(2)} km²`);
  console.log(`Surface water extent on Feb 2, 2020 (approx.): ${waterExtent2_km2.toFixed(2)} km²`);

  if (waterExtent2_km2 > waterExtent1_km2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
